import xml.etree.ElementTree as ET
from pathlib import Path
NS_URI='http://www.hancom.co.kr/hwpml/2010/HWPML'
NS={'hp':NS_URI}

def localname(tag):
    return tag.split('}')[-1] if '}' in tag else tag

def text(p):
    return ''.join((t.text or '') for t in p.findall('.//hp:t', NS))

for sec in ['section0.xml','section1.xml']:
    path=Path('/tmp/hwpx_verify/Contents')/sec
    root=ET.parse(path).getroot()
    for p in root.findall('.//hp:p', NS):
        t=text(p)
        if not t:
            continue
        if 'Asteron Commerce' in t or '한예진' in t or '2026-08-12' in t or 'Priority-24M' in t or 'renewals-escalation@asteron.example' in t or '가격 검토가 끝날 때까지' in t or '보안 검토 완료' in t or '결재 라인' in t or '온콜로 고정' in t:
            # ensure no linesegarray descendants
            has_cache=any(localname(el.tag).lower()=='linesegarray' for el in p.iter())
            if has_cache:
                raise SystemExit(f'Found linesegarray in modified paragraph id={p.get("id")} in {sec}: {t}')
print('No linesegarray found in modified paragraphs')
PY

