arguments.command:
python3 - <<'PY'
import xml.etree.ElementTree as ET
from pathlib import Path
NS_URI='http://www.hancom.co.kr/hwpml/2010/HWPML'
NS={'hp':NS_URI}

def paragraph_text(p):
    return ''.join((t.text or '') for t in p.findall('.//hp:t', NS))

def all_text(paths):
    out=[]
    for path in paths:
        root=ET.parse(path).getroot()
        for p in root.findall('.//hp:p', NS):
            out.append(paragraph_text(p))
    return '\n'.join(out)

paths=[Path('/tmp/hwpx_verify/Contents/section0.xml'), Path('/tmp/hwpx_verify/Contents/section1.xml')]
t=all_text(paths)
old_values=['Northwind','이전담당자','2025-04-01','2025-04-15','Standard-18M','ops-old@northwind.example','기존 메모를 새 메모로 바꾸세요.','old follow-up alpha','old follow-up beta','old follow-up gamma']
found=[v for v in old_values if v in t]
if found:
    raise SystemExit('Old values still present: '+', '.join(found))
new_values=['Asteron Commerce','한예진','2026-08-12','2026-08-26','Priority-24M','renewals-escalation@asteron.example','가격 검토가 끝날 때까지 할인 문구를 외부에 공유하지 마세요.']
missing=[v for v in new_values if v not in t]
if missing:
    raise SystemExit('Expected new values missing: '+', '.join(missing))
appendix='이 부록 문단은 그대로 유지해야 합니다.'
if appendix not in t:
    raise SystemExit('Appendix sentence missing/changed')
print('Old values absent; new values present; appendix intact')
PY

